negativeExample:
class NegativeTest {
    private String prefix = "Log: ";
    private static final String STATIC_PREFIX = "Static: ";

    public String logWithVariablePrefix(Object obj) {
        // Should NOT match: 'prefix' is a variable, not a string literal.
        return prefix + obj.toString();
    }

    public String logWithStaticFieldPrefix(Object obj) {
        // Should NOT match: 'STATIC_PREFIX' is a field reference, not a string literal.
        return STATIC_PREFIX + obj.toString();
    }

    public String directToStringCall(Object obj) {
        // Should NOT match: not part of a string concatenation.
        String value = obj.toString();
        return value;
    }
}
